values.content:
Analiza el siguiente CV contra los criterios de evaluación proporcionados.

## CRITERIOS DE EVALUACIÓN:
{{ $('Criterios de Evaluación').item.json.evaluationCriteria }}

## CONTENIDO DEL CV:
{{ $('Preparar Datos del CV').item.json.cvText }}

## INSTRUCCIONES:
Proporciona tu análisis en el siguiente formato JSON:

```json
{
  "candidato": {
    "nombre": "Nombre extraído del CV",
    "email": "Email si está disponible",
    "telefono": "Teléfono si está disponible",
    "ubicacion": "Ubicación del candidato"
  },
  "experiencia": {
    "anos_totales": 0,
    "experiencia_relevante": "Descripción breve",
    "empresas_destacadas": []
  },
  "educacion": {
    "nivel_maximo": "Licenciatura/Maestría/etc",
    "institucion": "Nombre de la institución",
    "carrera": "Nombre de la carrera",
    "cumple_requisito": true/false
  },
  "habilidades": {
    "requeridas_encontradas": [],
    "requeridas_faltantes": [],
    "deseables_encontradas": [],
    "otras_relevantes": []
  },
  "idiomas": {
    "cumple_requisitos": true/false,
    "detalle": []
  },
  "evaluacion": {
    "puntuacion_general": 0,
    "nivel_compatibilidad": "Alto/Medio/Bajo",
    "fortalezas": [],
    "areas_mejora": [],
    "recomendacion": "Avanzar a entrevista / Considerar para futuras vacantes / No cumple perfil",
    "notas_adicionales": ""
  }
}
```

La puntuación general debe ser de 0 a 100, donde:
- 80-100: Alta compatibilidad, candidato ideal
- 60-79: Buena compatibilidad, cumple mayoría de requisitos
- 40-59: Compatibilidad media, falta experiencia o habilidades clave
- 0-39: Baja compatibilidad, no cumple requisitos mínimos

parameters.jsCode:
// Parsear la respuesta del LLM
const llmResponse = $input.first().json.message.content;
const cvData = $('Preparar Datos del CV').first().json;

// Intentar extraer el JSON de la respuesta
let analysis;
try {
  // Buscar el JSON en la respuesta (puede venir con markdown)
  const jsonMatch = llmResponse.match(/```json\n?([\s\S]*?)\n?```/) || 
                   llmResponse.match(/\{[\s\S]*\}/);

  if (jsonMatch) {
    const jsonStr = jsonMatch[1] || jsonMatch[0];
    analysis = JSON.parse(jsonStr);
  } else {
    throw new Error('No se encontró JSON válido en la respuesta');
  }
} catch (error) {
  analysis = {
    error: 'Error al parsear respuesta del LLM',
    rawResponse: llmResponse
  };
}

// Preparar datos para Excel
const excelRow = {
  // Datos del archivo
  fecha_recepcion: cvData.receivedDate,
  nombre_archivo: cvData.fileName,
  id_archivo: cvData.fileId,

  // Datos del candidato
  nombre_candidato: analysis.candidato?.nombre || 'No disponible',
   email: analysis.candidato?.email || 'No disponible',
  telefono: analysis.candidato?.telefono || 'No disponible',
  ubicacion: analysis.candidato?.ubicacion || 'No disponible',

  // Experiencia
  anos_experiencia: analysis.experiencia?.anos_totales || 0,
  experiencia_relevante: analysis.experiencia?.experiencia_relevante || '',

  // Educación
  nivel_educativo: analysis.educacion?.nivel_maximo || '',
  carrera: analysis.educacion?.carrera || '',
  cumple_educacion: analysis.educacion?.cumple_requisito ? 'Sí' : 'No',

  // Habilidades
  habilidades_requeridas: (analysis.habilidades?.requeridas_encontradas || []).join(', '),
  habilidades_faltantes: (analysis.habilidades?.requeridas_faltantes || []).join(', '),
  habilidades_deseables: (analysis.habilidades?.deseables_encontradas || []).join(', '),

  // Idiomas
  cumple_idiomas: analysis.idiomas?.cumple_requisitos ? 'Sí' : 'No',

  // Evaluación
  puntuacion: analysis.evaluacion?.puntuacion_general || 0,
  nivel_compatibilidad: analysis.evaluacion?.nivel_compatibilidad || '',
  fortalezas: (analysis.evaluacion?.fortalezas || []).join('; '),
  areas_mejora: (analysis.evaluacion?.areas_mejora || []).join('; '),
  recomendacion: analysis.evaluacion?.recomendacion || '',
  notas: analysis.evaluacion?.notas_adicionales || '',

  // Análisis completo en JSON
  analisis_json: JSON.stringify(analysis, null, 2)
};

return [{ json: excelRow }];

